import asyncio,hashlib,inspect,json,os,sys,tempfile,time
from dataclasses import asdict
from pathlib import Path
from unittest.mock import patch
OUT=Path('.dev/health-reference-batches-probe.json');assert not OUT.exists()
out={'contract':'pa.health-reference-batches-probe/v1','scope':'Read-only referenced_hashes fetchmany(128) prototype, same DISTINCT query and complete reference set. Full fresh health remains uncached; no GC, write, lock, retention, warning or timeout change. Temporary roots only; network and workspace construction denied. This is not the rejected GC fetchall/aggregate hypothesis and not deployed acceptance.','cases':[],'seeding':[]}
def save():OUT.write_text(json.dumps(out,indent=2)+'\n')
def deny_network(event,args):
 if event=='socket.connect':raise AssertionError('Network denied in leaf health fixture')
sys.addaudithook(deny_network)
with tempfile.TemporaryDirectory(prefix='pa-health-reference-batches-') as tmp:
 root=Path(tmp).resolve();os.environ['PA_DATA_DIR']=str(root/'data');os.environ['PA_WORKSPACE_ROOT']=str(root/'workspaces');(root/'data').mkdir()
 from pa.repository.workspace import WorkspaceManager
 def denied(*a,**k):raise AssertionError('Workspace construction denied in leaf health fixture')
 WorkspaceManager.__init__=denied
 from pa.domain.transcript_storage import TranscriptStorage
 from pa.domain.models import TranscriptEvent
 from pa.core.async_runtime import AsyncRuntime
 from pa.core.performance import current_observation,distribution
 assert {'after_seq','limit'} <= set(inspect.signature(TranscriptStorage.list).parameters)
 original=TranscriptStorage.referenced_hashes
 def batched(self):
  with self._conn() as conn:
   cursor=conn.execute('SELECT DISTINCT cold_hash FROM transcript_events WHERE cold_hash IS NOT NULL')
   hashes=set()
   while rows:=cursor.fetchmany(128):hashes.update(row[0] for row in rows)
   return hashes
 out.update(source_sha256=hashlib.sha256(inspect.getsource(original).encode()).hexdigest(),candidate_source=inspect.getsource(batched),roots={'data':str(root/'data'),'workspace':str(root/'workspaces'),'workspace_construction':'denied','network':'denied'});save()
 def event(session,i,cold=True):return TranscriptEvent(session_id=session,seq=i+1,event_type='chunk',payload={'text':str(i)+(' cold fixture'*600 if cold else ' hot fixture')})
 s=TranscriptStorage(root/'data'/'metadata.db');n=12511
 try:
  for start in range(0,n,256):
   s.append([event('retained',i) for i in range(start,min(start+256,n))]);out['seeding'].append(min(start+256,n));save()
  expected=original(s);assert len(expected)==n and expected==batched(s)
  expected_digest=hashlib.sha256(json.dumps(sorted(expected)).encode()).hexdigest();baseline_health=s.metrics();assert baseline_health['missing_objects']==0
  async def run():
   runtime=AsyncRuntime()
   try:
    for workload in ('references','health'):
     for pair in range(8):
      methods=[('baseline',original),('batched',batched)]
      if pair%2:methods.reverse()
      for method,call in methods:
       def measure():
        start=time.perf_counter();cpu=time.thread_time()
        if workload=='references':
         value=call(s);count=len(value);digest=hashlib.sha256(json.dumps(sorted(value)).encode()).hexdigest();answer={'count':count,'digest':digest}
        else:
         with patch.object(TranscriptStorage,'referenced_hashes',call):answer=s.metrics()
        return {'wall_ms':(time.perf_counter()-start)*1000,'cpu_ms':(time.thread_time()-cpu)*1000,'answer':answer,'observed':{k:v for k,v in asdict(current_observation.get()).items() if isinstance(v,(int,float,bool))}}
       result=await runtime.run_blocking('probe.health_refs_'+method,measure);out['cases'].append({'workload':workload,'pair':pair,'method':method,**result});save()
       assert result['answer']==({'count':n,'digest':expected_digest} if workload=='references' else baseline_health)
    seq=0
    for pair in range(3):
     methods=[('baseline',original),('batched',batched)]
     if pair%2:methods.reverse()
     for method,call in methods:
      offset=seq;seq+=1024
      def writes():
       start=time.perf_counter()
