       return {'wall_ms':(time.perf_counter()-start)*1000,'cpu_ms':(time.thread_time()-cpu)*1000,'answer':answer,'observed':{k:v for k,v in asdict(current_observation.get()).items() if isinstance(v,(int,float,bool))}}
      result,append=await asyncio.gather(runtime.run_blocking('probe.health_refs_'+method,health),runtime.run_blocking('probe.health_refs_append',writes))
      out['cases'].append({'workload':'concurrent','pair':pair,'method':method,**result,'append':append});save()
      assert result['answer']['missing_objects']==0 and result['answer']['references']==n and append['rows']==1024
    out['summary']={work:{method:{k:distribution([r[k] for r in out['cases'] if r['workload']==work and r['method']==method]) for k in ('wall_ms','cpu_ms')} for method in ('baseline','batched')} for work in ('references','health','concurrent')}
    out['append_ms']={method:distribution([r['append']['wall_ms'] for r in out['cases'] if r['workload']=='concurrent' and r['method']==method]) for method in ('baseline','batched')};out['runtime']=runtime.snapshot();save()
